INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Betroffenenrechte > Recht auf Berichtigung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gewährt Art. 16 DSGVO Betroffenen das Recht, die Berichtigung unrichtiger personenbezogener Daten zu verlangen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 16 DSGVO garantiert das Berichtigungsrecht"}, {"text": "Nein", "correct": false, "because": "Recht ist gesetzlich verankert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Recht auf Berichtigung auch die Ergänzung unvollständiger Daten umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 16 DSGVO erlaubt Ergänzung unvollständiger Daten"}, {"text": "Nein", "correct": false, "because": "Ergänzung ist Teil des Rechts"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Unternehmen das Recht auf Berichtigung immer kostenfrei erfüllen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 12 Abs. 5 DSGVO schreibt Kostenfreiheit vor"}, {"text": "Nein", "correct": false, "because": "Kostenfreiheit ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Betroffene ihr Recht auf Berichtigung auch dann ausüben, wenn die Daten rechtmäßig verarbeitet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Recht gilt unabhängig von der Rechtmäßigkeit der Verarbeitung"}, {"text": "Nein", "correct": false, "because": "Recht ist universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Recht auf Berichtigung nach Art. 16 DSGVO an eine Frist gebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Keine spezifische Frist für die Ausübung, nur Bearbeitungsfrist"}, {"text": "Ja", "correct": false, "because": "Keine Ausübungsfrist vorgesehen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was erlaubt das Recht auf Berichtigung gemäß Art. 16 DSGVO Betroffenen?', 2, '[{"text": "Korrektur unrichtiger Daten", "correct": true, "because": "Art. 16 DSGVO definiert dies"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frist haben Unternehmen, um ein Berichtigungsverlangen nach Art. 16 DSGVO zu erfüllen?', 3, '[{"text": "Einen Monat", "correct": true, "because": "Art. 12 Abs. 3 DSGVO setzt eine Monatsfrist"}, {"text": "Drei Monate", "correct": false, "because": "Zu lang"}, {"text": "Keine Frist", "correct": false, "because": "Frist ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme müssen Unternehmen bei einem Berichtigungsverlangen ergreifen?', 2, '[{"text": "Daten korrigieren oder ergänzen", "correct": true, "because": "Pflicht nach Art. 16 DSGVO"}, {"text": "Daten löschen", "correct": false, "because": "Anderes Recht"}, {"text": "Daten ignorieren", "correct": false, "because": "Verstoß gegen DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grundsatz nach Art. 5 DSGVO wird durch das Recht auf Berichtigung unterstützt?', 2, '[{"text": "Richtigkeit", "correct": true, "because": "Art. 5 Abs. 1d fordert korrekte Daten"}, {"text": "Zweckbindung", "correct": false, "because": "Anderer Fokus"}, {"text": "Datenminimierung", "correct": false, "because": "Anderer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht Unternehmen bei Nichtbeachtung des Rechts auf Berichtigung?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen DSGVO strafbar"}, {"text": "Systemausfall", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Nicht relevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rechte umfasst das Recht auf Berichtigung nach Art. 16 DSGVO?', 4, '[{"text": "Korrektur unrichtiger Daten", "correct": true, "because": "Hauptzweck des Rechts"}, {"text": "Ergänzung unvollständiger Daten", "correct": true, "because": "Ebenfalls vorgesehen"}, {"text": "Nachweis der Richtigkeit", "correct": true, "because": "Betroffene können dies verlangen"}, {"text": "Datenweitergabe an Dritte", "correct": false, "because": "Kein Teil des Rechts"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen bei einem Berichtigungsverlangen?', 3, '[{"text": "Daten innerhalb eines Monats korrigieren", "correct": true, "because": "Frist nach Art. 12"}, {"text": "Betroffene informieren", "correct": true, "because": "Pflicht bei Korrektur"}, {"text": "Kostenfrei handeln", "correct": true, "because": "Art. 12 Abs. 5"}, {"text": "Daten löschen", "correct": false, "because": "Anderes Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten können gemäß Art. 16 DSGVO berichtigt werden?', 4, '[{"text": "Falsche Namen", "correct": true, "because": "Unrichtige Daten"}, {"text": "Veraltete Adressen", "correct": true, "because": "Nicht mehr korrekt"}, {"text": "Unvollständige Kontaktdaten", "correct": true, "because": "Ergänzung möglich"}, {"text": "Öffentliche Daten", "correct": false, "because": "Kein Personenbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann die Nichtbeachtung des Rechts auf Berichtigung haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen DSGVO strafbar"}, {"text": "Schadensersatz", "correct": true, "because": "Betroffene können klagen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kundenvertrauen schwindet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Softwareplanung unterstützen das Recht auf Berichtigung?', 3, '[{"text": "Datenvalidierung", "correct": true, "because": "Sichert korrekte Eingaben"}, {"text": "Benutzeroberfläche für Korrekturen", "correct": true, "because": "Erleichtert Anfragen"}, {"text": "Protokollierung von Änderungen", "correct": true, "because": "Nachweisbarkeit"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Widerspricht Speicherbegrenzung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Recht auf Berichtigung erlaubt die Korrektur unrichtiger Daten. b) Es umfasst keine Ergänzung unvollständiger Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Korrektur ja, Ergänzung auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unternehmen müssen Berichtigungen kostenfrei vornehmen. b) Die Frist beträgt drei Monate.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kostenfrei ja, Frist ein Monat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Recht auf Berichtigung unterstützt den Grundsatz der Richtigkeit. b) Es gilt nur bei unrechtmäßiger Verarbeitung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Richtigkeit ja, unabhängig von Rechtmäßigkeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Verstöße gegen das Recht auf Berichtigung können Bußgelder nach sich ziehen. b) Betroffene haben keine Frist zur Ausübung.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Bußgelder ja, keine Ausübungsfrist"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Datenvalidierung in Software unterstützt das Recht auf Berichtigung. b) Unternehmen müssen Betroffene bei Korrekturen nicht informieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Validierung ja, Information Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

